#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/* 任务时间段 */
typedef struct {
    int start;
    int end;
} Range;

Range* new_Range(int start, int end) {
    Range* range = (Range*) malloc(sizeof(Range));
    range->start = start;
    range->end = end;
    return range;
}

typedef Range E;

/* 优先队列实现 */
typedef struct PriorityQueue {
    E **arr;
    int size;
    int (*cmp)(const void *, const void *);
} PQ;

PQ *new_PQ(int capacity, int (*cmp)(const void *, const void *)) {
    PQ *pq = (PQ *) malloc(sizeof(PQ));
    pq->arr = (E **) malloc(sizeof(E *) * capacity);
    pq->size = 0;
    pq->cmp = cmp;
    return pq;
}

void swap_PQ(PQ *pq, int a, int b) {
    E *tmp = pq->arr[a];
    pq->arr[a] = pq->arr[b];
    pq->arr[b] = tmp;
}

// 上浮
void swim_PQ(PQ *pq) {
    int c = pq->size - 1;

    while (c >= 1) {
        int f = (c - 1) / 2;

        if (pq->cmp(pq->arr[c], pq->arr[f]) < 0) {
            swap_PQ(pq, c, f);
            c = f;
        } else {
            break;
        }
    }
}

// 入队
void offer_PQ(PQ *pq, E *val) {
    pq->arr[pq->size++] = val;
    swim_PQ(pq);
}

// 下沉
void sink_PQ(PQ *pq) {
    int f = 0;

    while (1) {
        int c1 = 2 * f + 1;
        int c2 = c1 + 1;

        int c;

        if (pq->size > c1 && pq->size > c2) {
            if (pq->cmp(pq->arr[c1], pq->arr[c2]) < 0) {
                c = c1;
            } else {
                c = c2;
            }
        } else if (pq->size > c1 && pq->size <= c2) {
            c = c1;
        } else if (pq->size <= c1 && pq->size > c2) {
            c = c2;
        } else {
            break;
        }

        if (pq->cmp(pq->arr[c], pq->arr[f]) < 0) {
            swap_PQ(pq, c, f);
            f = c;
        } else {
            break;
        }
    }
}

// 出队
E *poll_PQ(PQ *pq) {
    swap_PQ(pq, 0, pq->size - 1);
    E *res = pq->arr[--pq->size];
    sink_PQ(pq);
    return res;
}

int cmp(const void *a, const void *b) {
    Range *A = (Range *) a;
    Range *B = (Range *) b;
    // 结束时间越大（越晚）优先级越高，结束时间相同时，开始时间越大（越晚）优先级越高
    return A->end != B->end ? B->end - A->end : B->start - A->start;
}

int main() {
    int n;
    scanf("%d", &n);

    // 结束时间越大（越晚）优先级越高，结束时间相同时，开始时间越大（越晚）优先级越高
    PQ* pq = new_PQ(n, cmp);

    for (int i = 0; i < n; i++) {
        int start, end;
        scanf("%d %d", &start, &end);
        offer_PQ(pq, new_Range(start, end));
    }

    // 记录最大任务数
    int count = 0;

    // 记录上一个任务的执行时刻
    int last_end = INT_MAX;

    while (pq->size > 0) {
        Range* range = poll_PQ(pq);

        if (range->end < last_end) {
            // 当前任务结束时刻end < 上个任务结束时刻last_end，则当前任务选择在end时刻执行
            last_end = range->end;
            count++;
        } else if (last_end > range->start) {
            // 当前任务结束时刻end ≥ 上个任务结束时刻last_end，则更新当前任务的结束时间为last_end-1，后重新加入优先队列排队
            // 同时注意range新的结束时间last_end - 1不能小于range.start，否则该任务无法执行
            range->end = last_end - 1;
            offer_PQ(pq, range);
        }
    }

    printf("%d\n", count);

    return 0;
}
